#include <deque>
#include <iostream>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, k;
    std::cin >> n >> k;
    std::vector<int> a(n);
    for (int& x : a) std::cin >> x;

    std::deque<int> dq;
    bool first = true;

    for (int i = 0; i < n; ++i) {
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
        dq.push_back(i);
        if (dq.front() + k <= i) dq.pop_front();         // stale: j + k <= i
        if (i + 1 >= k) {
            if (!first) std::cout << ' ';
            std::cout << a[dq.front()];
            first = false;
        }
    }
    std::cout << '\n';
}
